const e = $('Build Confirmación').item.json;
const groq = $input.first().json;

let aiText =
  groq?.choices?.[0]?.message?.content ??
  groq?.output?.[0]?.content?.[0]?.text ??
  null;

if (typeof aiText === 'string') {
  aiText = aiText
    .replace(/^["'\s]+|["'\s]+$/g, '')
    .trim();
}

const fallback = e._fallback_outbound ?? e._outbound ?? { type: 'text', body: '✅ Listo.' };

const finalBody =
  aiText && aiText.length >= 15
    ? aiText
    : fallback.body;

return [{
  json: {
    ...e,
    _outbound: {
      type: 'text',
      body: finalBody
    },
    _fallback_outbound: undefined,
    _humanizer: undefined
  }
}];
